<?php
namespace App\Services;
use App\Enums\AppointmentStatus; use App\Models\Appointment; use App\Models\BlockedTime; use App\Models\Provider; use App\Models\Service; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\Cache;
class SlotService { public function __construct(private SlotCacheService $cache){} public function availableSlots(Provider $provider, Service $service, string $date, ?int $excludeAppointmentId=null, bool $useCache=true): array { $callback=fn()=> $this->generate($provider,$service,$date,$excludeAppointmentId); if(!$useCache||$excludeAppointmentId){return $callback();} return Cache::remember($this->cache->key($provider->id,$service->id,$date),config('booking.slot_cache_seconds',300),$callback); }
private function generate(Provider $provider, Service $service,string $date,?int $excludeAppointmentId): array { if(!$provider->is_active||!$service->is_active){return [];} $offering=$provider->services()->whereKey($service->id)->wherePivot('is_active',true)->first(); if(!$offering){return [];} $tz=$provider->timezone; $dayStart=CarbonImmutable::parse($date,$tz)->startOfDay(); $dayEnd=$dayStart->endOfDay(); $availabilities=$provider->availabilities()->where('day_of_week',$dayStart->dayOfWeek)->orderBy('start_time')->get(); if($availabilities->isEmpty()){return [];} $utcStart=$dayStart->utc(); $utcEnd=$dayEnd->utc(); $blocked=BlockedTime::query()->where('provider_id',$provider->id)->where('starts_at','<',$utcEnd)->where('ends_at','>',$utcStart)->get(); $appointments=Appointment::query()->where('provider_id',$provider->id)->when($excludeAppointmentId,fn($q)=>$q->where('id','!=',$excludeAppointmentId))->where('starts_at','<',$utcEnd)->where('ends_at','>',$utcStart)->where(function($q){$q->where('status',AppointmentStatus::Confirmed->value)->orWhere(function($q){$q->where('status',AppointmentStatus::Pending->value)->where('hold_expires_at','>',now());});})->get(); $duration=$service->duration_minutes; $slots=[]; foreach($availabilities as $availability){$cursor=CarbonImmutable::parse($date.' '.$availability->start_time,$tz);$windowEnd=CarbonImmutable::parse($date.' '.$availability->end_time,$tz);while($cursor->addMinutes($duration)->lte($windowEnd)){$end=$cursor->addMinutes($duration);$startUtc=$cursor->utc();$endUtc=$end->utc();$busy=$blocked->contains(fn($x)=>$this->overlaps($startUtc,$endUtc,$x->starts_at,$x->ends_at))||$appointments->contains(fn($x)=>$this->overlaps($startUtc,$endUtc,$x->starts_at,$x->ends_at));if(!$busy&&$startUtc->isFuture()){$slots[]=['starts_at'=>$startUtc->toIso8601String(),'ends_at'=>$endUtc->toIso8601String(),'local_start'=>$cursor->format('Y-m-d H:i'),'local_end'=>$end->format('Y-m-d H:i'),'timezone'=>$tz,'price'=>$offering->pivot->price,'currency'=>config('booking.currency')];}$cursor=$cursor->addMinutes($duration);}} return $slots; }
private function overlaps($aStart,$aEnd,$bStart,$bEnd): bool { return $aStart->lt($bEnd)&&$aEnd->gt($bStart); } }
